            lx.data.Extraction(extraction_class="organizations", extraction_text="Fugro Engineers B.V."),
            lx.data.Extraction(extraction_class="organizations", extraction_text="Eneco Round 3 Development Limited"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="Fugro GeoConsulting Limited"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="Fugro Alluvial  Offshore Limited"),
            lx.data.Extraction(extraction_class="marine species", extraction_text="Multi Cat  M/V Willendeavour"),
