            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Rye bay"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Hastings"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Rye harbour"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Eastbourne"),
            lx.data.Extraction(extraction_class="migratory marine species", extraction_text="fish"),
            lx.data.Extraction(extraction_class="migratory marine species", extraction_text="bass"),
