            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="depth"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="particle size information"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="suspended particulate matter"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="fluorescence"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="sediment settling velocity"),
