            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Fal estuary"),
            lx.data.Extraction(extraction_class="taxon", extraction_text="lithothamnion calcareum"),
            lx.data.Extraction(extraction_class="taxon", extraction_text="Cutleria multifida"),
            lx.data.Extraction(extraction_class="invasive species", extraction_text="parasitic slime mould"),
