            lx.data.Extraction(extraction_class="procedures", extraction_text="multibeam"),
            lx.data.Extraction(extraction_class="procedures", extraction_text="underwater cameras"),
            lx.data.Extraction(extraction_class="procedures", extraction_text="ground-truth sampling"),
