            lx.data.Extraction(extraction_class="organizations", extraction_text="Cardiff University"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="University of Birmingham"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="Durham University"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="RRS James Cook"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="School of Geography"),
