            lx.data.Extraction(extraction_class="geospatial region", extraction_text="River Fal"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Cornwall"),
            lx.data.Extraction(extraction_class="organizations", extraction_text="Cornwall Inshore Fisheries and Conservation Authority"),
            lx.data.Extraction(extraction_class="taxon", extraction_text="Mimachlamys varia"),
