            lx.data.Extraction(extraction_class="geospatial region", extraction_text="European sites"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Colne"),
            lx.data.Extraction(extraction_class="geospatial region", extraction_text="Roach"),
