            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="precipitation"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="wind velocities"),
            lx.data.Extraction(extraction_class="measurements and facts", extraction_text="fluorescence"),
